episodes.script:
// 详情接口一次返回整本分集，每集带 shortPlayList[].chapterShortPlayVoList[].shortPlayUrl。
// 该地址是带时效的签名直链，不能存进分集列表（下次打开会 403），
// 因此分集 url 只存「详情接口地址 + #ep=集记录ID」，点播时由 parseVideo 现取。
var XG_API = '/novel-api/basedata/book/getChapterList?bookId=';
var XG_QS = '&productId=2a8c14d1-72e7-498b-af23-381028eb47c0&vestId=2be070e0-c824-4d0e-a67a-8f688890cadb&channel=oppo19&osType=android&version=20&token=202509271001001446030204698626';
function xgStrip(base){ if (!base) return ''; return base.charAt(base.length-1)==='/' ? base.slice(0, base.length-1) : base; }
function xgParse(raw){ if (typeof raw !== 'string') return raw || {}; try { return JSON.parse(raw); } catch (e) { return {}; } }
function xgEpIdOf(node, index){
  var lists = node.shortPlayList || [];
  for (var k = 0; k < lists.length; k++) {
    var eps = lists[k].chapterShortPlayVoList || [];
    if (eps.length) return eps[0].id || node.chapterId || '';
  }
  return node.chapterId || String(index + 1);
}
function parseEpisodes(raw, context){
  var json = xgParse(raw);
  var data = (json && json.data) || [];
  if (!data.length) return [];
  var base = xgStrip((context && context.baseUrl) || '');
  var bookId = data[0].bookId || '';
  var api = base + XG_API + bookId + XG_QS;
  var out = [];
  for (var i = 0; i < data.length; i++) {
    var ch = data[i];
    out.push({
      id: String(ch.chapterId || ''),
      title: ch.chapterName || ('第' + (ch.chapterIndex || (i + 1)) + '集'),
      number: ch.chapterIndex || (i + 1),
      url: api + '#ep=' + encodeURIComponent(xgEpIdOf(ch, i))
    });
  }
  return out;
}
var XG_EP = '';
function xgFind(json, epId){
  var data = (json && json.data) || [];
  for (var i = 0; i < data.length; i++) {
    var lists = data[i].shortPlayList || [];
    for (var k = 0; k < lists.length; k++) {
      var eps = lists[k].chapterShortPlayVoList || [];
      for (var j = 0; j < eps.length; j++) {
        if (String(eps[j].id) === String(epId)) return eps[j].shortPlayUrl || '';
      }
    }
    if (String(data[i].chapterId) === String(epId)) {
      var first = ((data[i].shortPlayList || [])[0] || {}).chapterShortPlayVoList || [];
      if (first.length) return first[0].shortPlayUrl || '';
    }
  }
  return '';
}
function parseVideo(raw, context){
  var url = (context && context.url) || '';
  var cut = url.indexOf('#ep=');
  XG_EP = cut >= 0 ? decodeURIComponent(url.slice(cut + 4)) : '';
  var hit = xgFind(xgParse(raw), XG_EP);
  if (hit) return hit;
  var target = cut >= 0 ? url.slice(0, cut) : url;
  if (target.indexOf('http') === 0) {
    return { __meta: true, __fetchUrl: target, __fetchResponseType: 'json', __processor: 'xgPick' };
  }
  return '';
}
function xgPick(raw){ return xgFind(xgParse(raw), XG_EP); }

